internal actual fun createTelemetryNative(systemHandle: Long): TelemetryNative =
    TelemetryNativeImpl(NativeTelemetry.create(systemHandle))

internal actual class TelemetryCallbackGuard actual constructor() {
    private val claimed = AtomicBoolean(false)

    actual fun tryClaim(): Boolean = claimed.compareAndSet(false, true)
}
